<?php $title = $user['full_name'] . ' Profile'; require __DIR__ . '/../partials/header.php'; ?>
<main class="container narrow">
<section class="profile-hero card"><div class="cover"></div><div class="profile-body"><?php if (!empty($user['profile_image'])): ?><img class="profile-avatar avatar-photo" src="<?= e($user['profile_image']) ?>" alt="Profile picture"><?php else: ?><div class="profile-avatar"><?= e(strtoupper(substr($user['full_name'],0,1))) ?></div><?php endif; ?><h1><?= e($user['full_name']) ?></h1><p class="muted">@<?= e($user['username']) ?></p><p class="bio"><?= nl2br(e($user['bio'] ?: 'No bio yet.')) ?></p><?php if ((int)$user['id'] === (int)current_user_id()): ?><a class="button primary" href="index.php?page=profile_edit">Edit Profile</a><?php endif; ?></div></section>
<section class="card"><div class="section-title"><h2>Posts</h2><span><?= count($userPosts) ?></span></div><?php foreach ($userPosts as $post): ?><article class="profile-post"><div class="muted"><?= e($post['created_at']) ?></div><p><?= nl2br(e($post['content'])) ?></p><?php if (!empty($post['image'])): ?><img class="post-image" src="<?= e($post['image']) ?>" alt="Post image"><?php endif; ?><?php if ((int)$user['id'] === (int)current_user_id()): ?><a href="index.php?page=post_edit&id=<?= (int)$post['id'] ?>">Edit</a><?php endif; ?></article><?php endforeach; ?></section>
</main>
